changeSet.sql:
UPDATE process SET process_description = 'Framework ágil baseado no empirismo (transparência, inspeção e adaptação), estruturado em ciclos de duração fixa chamados sprints. Organiza o desenvolvimento por meio de um objetivo do produto (Product Goal), metas por sprint e entregas incrementais prontas para uso. Neste catálogo, o processo abrange desde a estruturação contínua do backlog e o planejamento da sprint até a execução diária, os eventos de inspeção e adaptação e a liberação em produção.' WHERE id = 1;
UPDATE process SET process_description = 'Método de gestão evolutiva voltado à visualização do trabalho, ao controle do trabalho em andamento (WIP) e à definição de políticas explícitas. O processo parte do entendimento da demanda e do mapeamento do fluxo (abordagem STATIK), avança para a operação por sistema puxado e se consolida em cadências regulares de revisão de entrega e de riscos. É indicado para serviços contínuos de engenharia de software que exigem previsibilidade de fluxo sem depender de iterações fixas.' WHERE id = 2;
UPDATE process SET process_description = 'Método ágil focada na excelência técnica de engenharia de software e na colaboração constante com o representante do negócio. Combina planejamento iterativo por histórias de usuário, desenvolvimento guiado por testes (TDD), programação em pares, projeto simples, integração contínua e entregas frequentes de pequeno porte. O objetivo é manter o custo de mudança baixo ao longo do tempo e validar o software continuamente em ciclos curtos.' WHERE id = 3;
UPDATE process SET process_description = 'Processo iterativo e incremental derivado do Processo Unificado (Rational Unified Process), organizado nas fases de Iniciação, Elaboração, Construção e Transição. Cada fase é concluída por um marco de avaliação que verifica objetivos de negócio, estabilidade arquitetural, capacidade operacional e prontidão para implantação. Esta versão simplificada preserva a gestão de riscos técnicos e a orientação à arquitetura de referência, enxugando a carga documental para equipes enxutas.' WHERE id = 4;
UPDATE phase SET name = 'Product Backlog', description = 'Etapa contínua de estruturação e evolução do backlog do produto, orientada pelo objetivo de longo prazo (Product Goal). Compreende a identificação de necessidades, a redação de histórias de usuário, a priorização por valor e o refinamento técnico e funcional antes das sprints. Garante que a equipe tenha sempre itens claros, viáveis e alinhados à estratégia do negócio.' WHERE id = 101;
UPDATE phase SET name = 'Planejamento da Sprint', description = 'Fase correspondente ao evento de abertura da sprint (Sprint Planning), na qual a equipe estabelece a meta do ciclo (Sprint Goal), seleciona os itens prioritários do backlog e define o plano técnico de entrega. Resulta no backlog da sprint, firmando um compromisso realista com base na capacidade produtiva da equipe.' WHERE id = 102;
UPDATE phase SET name = 'Execução da Sprint', description = 'Período de construção, integração e validação contínua em que os itens planejados são transformados em um incremento de software funcional. Envolve o alinhamento diário da equipe (Daily Scrum) para inspecionar o avanço em direção à meta da sprint, remover impedimentos e assegurar o cumprimento dos critérios de conclusão (Definition of Done).' WHERE id = 103;
UPDATE phase SET name = 'Encerramento da Sprint', description = 'Ciclo de inspeção e adaptação ao término da sprint, composto pela revisão do incremento com as partes interessadas (Sprint Review) e pela retrospectiva interna da equipe (Sprint Retrospective). Permite validar o produto construído para ajustar prioridades futuras e aprimorar continuamente o processo de trabalho.' WHERE id = 104;
UPDATE phase SET name = 'Release', description = 'Fase dedicada à estabilização final, preparação de ambiente e publicação do incremento em produção. Atende cenários em que a liberação para os usuários finais exige validações adicionais de segurança, desempenho ou janelas controladas de implantação após o término da sprint.' WHERE id = 105;
UPDATE phase SET name = 'Design do Sistema de Fluxo (STATIK)', description = 'Etapa de concepção do sistema Kanban segundo a abordagem sistêmica STATIK (Systems Thinking Approach to Introducing Kanban). Compreende a análise das fontes de demanda, o mapeamento das etapas reais de trabalho e a definição das classes de serviço, formando a base do quadro visual.' WHERE id = 201;
UPDATE phase SET name = 'Políticas Explícitas e WIP', description = 'Fase de estruturação da governança do fluxo, na qual se determinam os limites de trabalho em andamento (WIP) e as regras explícitas de transição entre as colunas. Estabelece as condições objetivas para puxar novos itens e evita a sobrecarga da equipe.' WHERE id = 202;
UPDATE phase SET name = 'Fluxo de Entrega', description = 'Operação contínua do sistema puxado: reabastecimento da fila de entrada, puxada de itens conforme a capacidade disponível, execução técnica e coleta de métricas de desempenho. Mantém o trabalho fluindo de forma previsível e expõe gargalos operacionais no dia a dia.' WHERE id = 203;
UPDATE phase SET name = 'Cadências de Melhoria', description = 'Ciclos periódicos de avaliação e evolução do serviço Kanban, incluindo a revisão de entrega do serviço (Service Delivery Review) e a revisão de riscos (Risk Review). Utiliza os indicadores de fluxo coletados para recalibrar limites, políticas e prioridades junto ao negócio.' WHERE id = 204;
UPDATE phase SET name = 'Release Planning', description = 'Fase de alinhamento entre o representante do negócio (cliente) e a equipe técnica por meio do jogo de planejamento (Planning Game). Define o escopo da próxima versão, estima o esforço das histórias de usuário e seleciona o que será construído em cada iteração curta.' WHERE id = 301;
UPDATE phase SET name = 'Ciclo da Story', description = 'Núcleo de construção do Extreme Programming para cada história de usuário. Integra a especificação de testes de aceitação, o desenvolvimento guiado por testes (TDD), a programação em pares e a integração contínua, assegurando validação técnica imediata durante a codificação.' WHERE id = 302;
UPDATE phase SET name = 'Práticas de Design Contínuo', description = 'Disciplinas que preservam a qualidade interna e a clareza da arquitetura ao longo das iterações: projeto simples, refatoração constante, uso da metáfora do sistema e adoção de padrões coletivos de código. Evitam a degradação estrutural sem exigir uma fase longa de projeto prévio.' WHERE id = 303;
UPDATE phase SET name = 'Feedback e Release', description = 'Etapa de validação funcional junto ao cliente presente, publicação de versões pequenas e frequentes (small releases) e realimentação do planejamento. Garante que o software evolua em estreita sintonia com as prioridades reais do negócio.' WHERE id = 304;
UPDATE phase SET name = 'Iniciação', description = 'Primeira fase do RUP, voltada à delimitação do escopo, ao alinhamento da visão de negócio e à análise de viabilidade do empreendimento. Encerra-se no marco de Objetivos do Ciclo de Vida (Lifecycle Objectives), quando se decide pela continuidade do projeto com base nos riscos e custos estimados.' WHERE id = 401;
UPDATE phase SET name = 'Elaboração', description = 'Fase dedicada ao detalhamento dos requisitos estruturantes, à validação da arquitetura de linha de base (baseline) e à mitigação dos principais riscos técnicos. Conclui-se no marco de Arquitetura do Ciclo de Vida (Lifecycle Architecture), garantindo fundações estáveis para a codificação em larga escala.' WHERE id = 402;
UPDATE phase SET name = 'Construção', description = 'Fase de desenvolvimento iterativo e integração incremental dos componentes de software sobre a arquitetura estabilizada, acompanhada de testes sistemáticos. Conduz o produto até o marco de Capacidade Operacional Inicial (Initial Operational Capability), quando o sistema está apto para implantação assistida.' WHERE id = 403;
UPDATE phase SET name = 'Transição', description = 'Fase final de entrega da solução aos usuários, compreendendo testes de aceitação em ambiente real, implantação em produção e transferência para a equipe de operação. Culmina no marco de Lançamento do Produto (Product Release), formalizando o encerramento do ciclo.' WHERE id = 404;

            UPDATE activity SET name = 'Estabelecer Product Goal e visão', description = 'Definir a visão do produto e o objetivo estratégico de longo prazo (Product Goal) em conjunto com as partes interessadas. Essa definição orienta as decisões de escopo e evita que o backlog se torne uma lista desconexa de pedidos. Serve como referência para avaliar o valor gerado a cada sprint.', input_criterion = 'Problema ou oportunidade de negócio identificados junto às partes interessadas' WHERE id = 1001;
            INSERT INTO activity (id, name, description, input_criterion, phase_id, created_by, last_modified_by)
SELECT 1013, 'Elaborar itens e histórias de usuário no Product Backlog', 'Traduzir as necessidades de negócio em itens do backlog do produto, geralmente descritos como histórias de usuário focadas no valor para quem utiliza o sistema. Em processos ágeis, os itens nascem de forma enxuta e são detalhados progressivamente antes de entrarem em execução. Esta atividade estrutura o backlog inicial para viabilizar sua priorização.', 'Objetivo do produto e documento de visão acordados', 101, 'system', 'system'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM activity WHERE id = 1013);
            UPDATE activity SET name = 'Elaborar itens e histórias de usuário no Product Backlog', description = 'Traduzir as necessidades de negócio em itens do backlog do produto, geralmente descritos como histórias de usuário focadas no valor para quem utiliza o sistema. Em processos ágeis, os itens nascem de forma enxuta e são detalhados progressivamente antes de entrarem em execução. Esta atividade estrutura o backlog inicial para viabilizar sua priorização.', input_criterion = 'Objetivo do produto e documento de visão acordados' WHERE id = 1013;
            UPDATE activity SET name = 'Ordenar Product Backlog por valor', description = 'Organizar os itens do backlog considerando o valor de negócio, os riscos associados, as dependências técnicas e a estimativa de esforço. A ordenação mantém no topo do backlog aquilo que entrega maior retorno e aprendizado no curto prazo, orientando o que será puxado nas próximas sprints.', input_criterion = 'Backlog do produto estruturado com histórias de usuário ou demandas iniciais' WHERE id = 1002;
            UPDATE activity SET name = 'Refinar Product Backlog', description = 'Detalhar, fatiar e estimar os itens prioritários do backlog até que atendam aos critérios de prontidão acordados pela equipe (Definition of Ready). Inclui esclarecer regras de negócio, definir critérios de aceitação verificáveis e reduzir incertezas de interface ou arquitetura antes do planejamento da sprint.', input_criterion = 'Backlog ordenado com itens candidatos à próxima sprint identificados' WHERE id = 1003;
            UPDATE activity SET name = 'Conduzir Sprint Planning', description = 'Realizar a reunião de planejamento da sprint para definir a meta do ciclo (Sprint Goal), selecionar os itens do backlog do produto e decompor o trabalho inicial de implementação. O resultado é o backlog da sprint, pactuado de forma colaborativa conforme a capacidade real da equipe.', input_criterion = 'Itens prioritários do backlog refinados e capacidade da equipe conhecida' WHERE id = 1004;
            UPDATE activity SET name = 'Conduzir Daily Scrum', description = 'Promover a reunião diária da equipe de desenvolvimento para inspecionar o progresso rumo à meta da sprint e ajustar o plano de trabalho das próximas 24 horas. O foco é a coordenação técnica entre os membros e a identificação rápida de bloqueios, evitando o formato de prestação de contas individual.', input_criterion = 'Sprint em andamento com meta e backlog da sprint estabelecidos' WHERE id = 1005;
            UPDATE activity SET name = 'Desenvolver Incremento da Sprint', description = 'Projetar, codificar e testar os itens selecionados na sprint, entregando funcionalidades integradas de ponta a ponta. O desenvolvimento deve observar os padrões de engenharia da equipe e manter o foco no atingimento da meta acordada para o ciclo.', input_criterion = 'Backlog da sprint planejado e comprometido pela equipe' WHERE id = 1006;
            UPDATE activity SET name = 'Integrar e verificar Incremento', description = 'Unificar o código produzido pela equipe no repositório principal, executando a bateria de testes automatizados e validando o funcionamento conjunto das funcionalidades. A integração frequente reduz conflitos tardios e garante que o incremento permaneça estável e funcional durante a sprint.', input_criterion = 'Funcionalidades da sprint codificadas e enviadas ao controle de versão' WHERE id = 1007;
            UPDATE activity SET name = 'Inspecionar qualidade técnica do Incremento', description = 'Realizar a revisão técnica do código, da cobertura de testes e dos requisitos de segurança para comprovar que o incremento cumpre integralmente os critérios de conclusão (Definition of Done). Essa verificação previne o acúmulo de dívida técnica antes da demonstração do produto.', input_criterion = 'Incremento integrado com compilação e testes automatizados aprovados' WHERE id = 1008;
            UPDATE activity SET name = 'Conduzir Sprint Review', description = 'Apresentar o incremento concluído às partes interessadas para validar as entregas em funcionamento e colher percepções sobre o uso do produto. Trata-se de uma sessão de trabalho colaborativa que avalia o avanço em direção ao objetivo do produto e subsidia adaptações no backlog.', input_criterion = 'Incremento concluído conforme os critérios de pronto e preparado para demonstração' WHERE id = 1009;
            UPDATE activity SET name = 'Conduzir Sprint Retrospective', description = 'Analisar coletivamente a dinâmica de trabalho da sprint encerrada, abrangendo interações da equipe, práticas de engenharia e ferramentas utilizadas. O encontro deve resultar em ações práticas de melhoria para aplicação já na sprint seguinte, sustentando a evolução contínua do processo.', input_criterion = 'Revisão da sprint concluída com os apontamentos do ciclo registrados' WHERE id = 1010;
            UPDATE activity SET name = 'Estabilizar candidato a release', description = 'Executar validações finais de regressão, desempenho e configuração, além de consolidar o pacote e as notas da versão candidata à publicação. Essa etapa prepara o incremento para o ambiente produtivo quando há exigências operacionais adicionais além do ciclo normal da sprint.', input_criterion = 'Incremento validado na revisão da sprint e decisão de lançamento confirmada' WHERE id = 1011;
            UPDATE activity SET name = 'Implantar Incremento em produção', description = 'Publicar a versão estabilizada no ambiente de produção, executar verificações pós-implantação e acompanhar os indicadores iniciais de operação. Conclui a entrega de valor aos usuários finais com segurança e rastreabilidade.', input_criterion = 'Pacote de lançamento homologado e procedimentos de implantação definidos' WHERE id = 1012;
            UPDATE activity SET name = 'Conduzir análise de demanda', description = 'Levantar a natureza, a frequência de chegada e a variabilidade dos pedidos que ingressam na equipe (novas funcionalidades, correções, suporte, melhorias técnicas). Compreender o perfil da demanda é o primeiro passo do método STATIK para desenhar um fluxo aderente à realidade operacional.', input_criterion = 'Contexto do serviço e canais de entrada de demandas identificados' WHERE id = 2001;
            UPDATE activity SET name = 'Mapear fluxo de trabalho atual', description = 'Representar visualmente a sequência real de atividades pelas quais um item passa, desde a solicitação até a entrega em produção, identificando estados de execução ativa e filas de espera. O mapeamento foca na realidade praticada pela equipe, expondo gargalos e pontos de retrabalho.', input_criterion = 'Análise de demanda concluída com os tipos de trabalho categorizados' WHERE id = 2002;
            UPDATE activity SET name = 'Definir classes de serviço', description = 'Estabelecer categorias de atendimento — como Urgente (Expedite), Data Fixa, Padrão e Intangível — associadas ao impacto do atraso (custo de atraso) de cada demanda. As classes de serviço definem regras claras de priorização e alocação de capacidade dentro do quadro Kanban.', input_criterion = 'Fluxo de trabalho mapeado e validado com a equipe responsável pelo serviço' WHERE id = 2003;
            UPDATE activity SET name = 'Estabelecer limites de WIP', description = 'Determinar a quantidade máxima de itens que podem permanecer simultaneamente em cada etapa ou raia do quadro (limite de trabalho em andamento). Essa restrição estimula a conclusão das atividades iniciadas antes da abertura de novas frentes, reduzindo a troca de contexto e o tempo de ciclo.', input_criterion = 'Classes de serviço definidas e capacidade produtiva da equipe estimada' WHERE id = 2004;
            UPDATE activity SET name = 'Formalizar políticas explícitas de fluxo', description = 'Documentar de maneira clara e visível os critérios técnicos e operacionais exigidos para que um item ingresse em uma coluna, seja puxado para a etapa seguinte ou seja considerado concluído. Políticas explícitas alinham o padrão de qualidade e eliminam ambiguidades na operação diária.', input_criterion = 'Limites de trabalho em andamento (WIP) definidos para as etapas do quadro' WHERE id = 2005;
            UPDATE activity SET name = 'Conduzir reunião de replenishment', description = 'Realizar o encontro periódico de reabastecimento com as partes interessadas para selecionar quais demandas aguardando triagem devem ingressar no ponto de compromisso do quadro. A seleção respeita as vagas disponíveis no sistema e o equilíbrio entre as classes de serviço.', input_criterion = 'Políticas do fluxo publicadas e capacidade disponível na fila de entrada' WHERE id = 2006;
            UPDATE activity SET name = 'Puxar item conforme capacidade disponível', description = 'Iniciar o atendimento de um novo item do ponto de compromisso ou da etapa anterior somente quando houver vaga abaixo do limite de trabalho em andamento (WIP), observando a prioridade da classe de serviço. O acionamento por puxada preserva o ritmo sustentável e evita filas internas.', input_criterion = 'Vaga disponível abaixo do limite de trabalho em andamento na coluna de destino' WHERE id = 2007;
            UPDATE activity SET name = 'Executar e validar item de trabalho', description = 'Desenvolver, revisar e testar o item em andamento até que cumpra todos os critérios de saída definidos para a etapa atual do fluxo. A verificação de qualidade integrada em cada coluna impede a propagação de defeitos para os estágios seguintes.', input_criterion = 'Item puxado para execução com seus critérios de entrada atendidos' WHERE id = 2008;
            UPDATE activity SET name = 'Registrar métricas de fluxo', description = 'Consolidar os indicadores quantitativos do sistema Kanban, como tempo total de atravessamento (lead time), tempo de execução (cycle time), taxa de entrega (vazão) e idade dos itens em andamento. Esses dados oferecem base empírica para prever prazos e diagnosticar restrições no processo.', input_criterion = 'Itens concluídos no período analisado ou lote de trabalho em andamento monitorado' WHERE id = 2009;
            UPDATE activity SET name = 'Conduzir Service Delivery Review', description = 'Avaliar periodicamente o desempenho do serviço prestado junto aos representantes do negócio, confrontando as métricas de entrega e a satisfação dos clientes com os acordos estabelecidos. A revisão orienta ajustes de priorização e expectativas de prazo.', input_criterion = 'Indicadores de fluxo do período consolidados para análise' WHERE id = 2010;
            UPDATE activity SET name = 'Conduzir Risk Review e evoluir o sistema', description = 'Examinar bloqueios recorrentes, dependências externas, falhas de qualidade e desvios de previsibilidade para recalibrar limites de WIP, colunas ou políticas explícitas. Fecha o ciclo de melhoria contínua, mantendo o sistema Kanban adaptado às mudanças do ambiente.', input_criterion = 'Revisão de entrega do serviço realizada e eventos de risco ou bloqueio mapeados' WHERE id = 2011;
            UPDATE activity SET name = 'Definir escopo e prioridades do release', description = 'Conduzir o jogo de planejamento (Planning Game) em que o cliente apresenta as necessidades de valor e a equipe técnica avalia implicações e riscos para compor o escopo da versão (release). O resultado é um plano equilibrado entre prioridade de negócio e viabilidade técnica.', input_criterion = 'Documento de visão acordado e histórias de usuário candidatas identificadas' WHERE id = 3001;
            UPDATE activity SET name = 'Estimar stories com planning poker', description = 'Estimar de maneira colaborativa o esforço relativo das histórias candidatas ao lançamento, promovendo o debate técnico para nivelar o entendimento da equipe. No XP, a estimativa dimensiona a capacidade das iterações e expõe incertezas precocemente.', input_criterion = 'Escopo da versão definido com histórias de usuário candidatas selecionadas' WHERE id = 3002;
            UPDATE activity SET name = 'Selecionar stories da iteração', description = 'Escolher o subconjunto de histórias estimadas que será implementado na iteração atual, respeitando a velocidade histórica da equipe. Esse compromisso de curto prazo dá origem ao backlog da iteração e mantém o foco em entregas incrementais constantes.', input_criterion = 'Histórias estimadas e velocidade ou capacidade da iteração conhecidas' WHERE id = 3003;
            UPDATE activity SET name = 'Escrever testes de aceitação da story', description = 'Especificar, com o apoio do cliente, os cenários e critérios de verificação que comprovarão o funcionamento correto da história de usuário. Definir os testes de aceitação antes ou no início da codificação transforma expectativas de negócio em metas objetivas para os desenvolvedores.', input_criterion = 'História selecionada para a iteração com regras de negócio discutidas com o cliente' WHERE id = 3004;
            UPDATE activity SET name = 'Aplicar ciclo TDD na story', description = 'Implementar a funcionalidade seguindo o desenvolvimento guiado por testes (TDD): escrever um teste automatizado que falha, codificar a solução mínima para aprová-lo e refatorar o código para limpar sua estrutura. Essa prática produz código testável por construção e reduz a introdução de defeitos.', input_criterion = 'Critérios de aceitação e casos de teste iniciais da história definidos' WHERE id = 3005;
            UPDATE activity SET name = 'Desenvolver story em pair programming', description = 'Construir o código de produção trabalhando em dupla no mesmo equipamento ou sessão compartilhada, alternando os papéis de condução da escrita e de revisão estratégica. A programação em pares eleva a qualidade do projeto, reduz falhas lógicas e nivela o conhecimento do sistema na equipe.', input_criterion = 'História em desenvolvimento com suíte de testes unitários em evolução' WHERE id = 3006;
            UPDATE activity SET name = 'Integrar continuamente na mainline', description = 'Incorporar as alterações no ramo principal do controle de versão várias vezes ao dia, acionando a compilação e a bateria completa de testes automatizados. A integração contínua detecta incompatibilidades imediatamente e mantém o sistema sempre pronto para liberação.', input_criterion = 'História codificada e aprovada nos testes locais da dupla de desenvolvimento' WHERE id = 3007;
            UPDATE activity SET name = 'Aplicar design simples', description = 'Manter a estrutura do código o mais simples possível para atender estritamente aos requisitos atuais, evitando abstrações especulativas (princípio YAGNI). Aliada à refatoração contínua, essa diretriz facilita a compreensão e a evolução do sistema nas iterações seguintes.', input_criterion = 'História em implementação com requisitos funcionais claros' WHERE id = 3008;
            UPDATE activity SET name = 'Evoluir metáfora do sistema', description = 'Estabelecer e refinar uma analogia ou vocabulário conceitual compartilhado entre negócio e engenharia para denominar módulos, classes e fluxos do sistema. A metáfora no XP substitui documentações extensas por um modelo mental comum sobre como a arquitetura se organiza.', input_criterion = 'Escopo da versão definido e conceitos centrais do domínio discutidos com a equipe' WHERE id = 3009;
            UPDATE activity SET name = 'Aplicar padrões de codificação coletivos', description = 'Adotar convenções uniformes de nomenclatura, formatação e estruturação de código, viabilizando a propriedade coletiva sobre todo o repositório. Com código padronizado, qualquer dupla consegue manter ou evoluir qualquer módulo sem depender de especialistas isolados.', input_criterion = 'Código da iteração integrado na linha principal do repositório' WHERE id = 3010;
            UPDATE activity SET name = 'Validar stories com testes de aceitação', description = 'Executar a bateria de testes de aceitação junto ao cliente presencial para comprovar que as histórias integradas atendem ao comportamento esperado pelo negócio. A validação direta encerra o ciclo da história com transparência sobre o valor efetivamente entregue.', input_criterion = 'Pacote da iteração integrado e disponível em ambiente de verificação' WHERE id = 3011;
            UPDATE activity SET name = 'Publicar small release', description = 'Colocar em produção ou em ambiente de homologação final uma versão enxuta e funcional do produto contendo as histórias aceitas. Lançamentos pequenos e frequentes antecipam o retorno sobre o investimento e reduzem o risco operacional de grandes implantações.', input_criterion = 'Histórias da iteração ou do ciclo validadas nos testes de aceitação' WHERE id = 3012;
            UPDATE activity SET name = 'Incorporar feedback do cliente presencial', description = 'Coletar as impressões do cliente e dos usuários sobre a versão liberada, convertendo aprendizados e novas necessidades em ajustes de prioridade ou novas histórias no backlog. Fecha o ciclo iterativo do XP e alimenta o próximo planejamento.', input_criterion = 'Versão demonstrada ou publicada e retorno do cliente registrado com a equipe' WHERE id = 3013;
            UPDATE activity SET name = 'Capturar visão e escopo do negócio', description = 'Levantar e registrar o problema organizacional, as partes interessadas, os objetivos estratégicos e as fronteiras do sistema na disciplina de Modelagem de Negócios e Requisitos. O documento de visão resultante alinha patrocinadores e equipe técnica antes do detalhamento funcional.', input_criterion = 'Oportunidade ou necessidade de negócio identificada no contexto da organização' WHERE id = 4001;
            UPDATE activity SET name = 'Identificar atores e casos de uso essenciais', description = 'Mapear os atores externos e os casos de uso de maior relevância que sintetizam o comportamento central esperado do sistema. Na fase de Iniciação do RUP, prioriza-se a abrangência do escopo funcional sem aprofundar fluxos periféricos precocemente.', input_criterion = 'Documento de visão e escopo preliminar aprovados pelas partes interessadas' WHERE id = 4002;
            UPDATE activity SET name = 'Avaliar viabilidade e riscos do projeto', description = 'Analisar a viabilidade técnica, financeira e de prazo do projeto, catalogando os riscos críticos e as estratégias iniciais de mitigação na disciplina de Gerenciamento de Projeto. Fundamenta a tomada de decisão do marco de Objetivos do Ciclo de Vida (Lifecycle Objectives).', input_criterion = 'Casos de uso essenciais mapeados e restrições do projeto levantadas' WHERE id = 4003;
            UPDATE activity SET name = 'Detalhar requisitos e regras de negócio', description = 'Especificar de forma estruturada os fluxos dos casos de uso prioritários, as regras de negócio, os requisitos não funcionais e os protótipos de interface necessários. Fornece insumos precisos para o desenho da arquitetura e para o planejamento dos testes na fase de Elaboração.', input_criterion = 'Marco de Objetivos do Ciclo de Vida aprovado e riscos iniciais registrados' WHERE id = 4004;
            UPDATE activity SET name = 'Definir arquitetura baseline', description = 'Projetar e validar a arquitetura de referência do sistema (baseline), definindo subsistemas, camadas, integrações e padrões estruturais na disciplina de Análise e Projeto. Uma linha de base arquitetural sólida sustenta o trabalho paralelo da equipe durante a fase de Construção.', input_criterion = 'Especificação dos requisitos estruturantes validada na Elaboração' WHERE id = 4005;
            UPDATE activity SET name = 'Construir protótipo de risco arquitetural', description = 'Desenvolver uma prova de conceito executável voltada exclusivamente a testar integrações complexas, requisitos severos de desempenho ou tecnologias inéditas. Permite eliminar as maiores incertezas técnicas antes de aprovar o marco de Arquitetura do Ciclo de Vida.', input_criterion = 'Riscos arquiteturais priorizados e critérios de avaliação do protótipo definidos' WHERE id = 4006;
            UPDATE activity SET name = 'Implementar componentes da iteração', description = 'Codificar, testar unitariamente e revisar os módulos e serviços previstos para a iteração corrente, seguindo a arquitetura de linha de base estabelecida. Na disciplina de Implementação do RUP, o sistema cresce de forma incremental ao longo de múltiplas iterações de construção.', input_criterion = 'Marco de Arquitetura do Ciclo de Vida aprovado e linha de base disponível' WHERE id = 4007;
            UPDATE activity SET name = 'Executar testes de integração de componentes', description = 'Verificar o funcionamento conjunto dos subsistemas e componentes desenvolvidos na iteração, validando contratos de interface, persistência e fluxos ponta a ponta. Na disciplina de Teste, essa etapa assegura que as partes integradas operem sem regressões.', input_criterion = 'Componentes da iteração implementados e disponibilizados em ambiente de integração' WHERE id = 4008;
            UPDATE activity SET name = 'Produzir build de iteração', description = 'Compilar, empacotar e versionar o conjunto integrado de componentes aprovados nos testes, gerando uma versão estável e rastreável na disciplina de Configuração e Mudança. Essa versão serve de base para demonstrações intermediárias e para a transição futura.', input_criterion = 'Testes de integração da iteração concluídos sem defeitos impeditivos' WHERE id = 4009;
            UPDATE activity SET name = 'Conduzir testes de aceitação com usuários', description = 'Executar os cenários de validação funcional e operacional com representantes reais dos usuários em ambiente de homologação (UAT). Confirma se o software construído atende às necessidades do negócio antes da liberação definitiva.', input_criterion = 'Versão integrada e estável implantada em ambiente de homologação' WHERE id = 4010;
            UPDATE activity SET name = 'Implantar solução no ambiente alvo', description = 'Executar o procedimento de publicação da versão homologada no ambiente de produção, incluindo migrações de dados, configurações de infraestrutura e verificações de integridade na disciplina de Implantação. Disponibiliza o sistema de forma controlada para operação real.', input_criterion = 'Aceite formal dos usuários registrado e plano de implantação validado' WHERE id = 4011;
            UPDATE activity SET name = 'Encerrar fase e transferir operação', description = 'Realizar a passagem de conhecimento e da documentação operacional para a equipe de sustentação, avaliar o cumprimento dos objetivos do projeto e registrar as lições aprendidas. Formaliza o marco de Lançamento do Produto (Product Release) e o fechamento do ciclo.', input_criterion = 'Sistema em operação estável no ambiente produtivo' WHERE id = 4012;

UPDATE roles SET description = 'Responsável por maximizar o valor do produto e por ordenar o backlog conforme essa prioridade. Traduz necessidades de negócio e das partes interessadas em objetivos claros para a equipe. No Scrum, é o papel com responsabilidade formal sobre o produto, não apenas apoio ocasional à priorização.' WHERE id = 1;
UPDATE roles SET description = 'Papel do Scrum voltado à eficácia da equipe, do Product Owner e da organização na aplicação do método. Facilita eventos, promove transparência, inspeção e adaptação e remove impedimentos. Diferencia-se de um facilitador genérico por atuar dentro das regras e valores do Scrum.' WHERE id = 2;
UPDATE roles SET description = 'Implementa lógica de servidor, APIs, persistência e integrações que sustentam o produto. Colabora na definição técnica de contratos e na qualidade do código sob sua área. Entrega incrementos testáveis alinhados à arquitetura acordada.' WHERE id = 3;
UPDATE roles SET description = 'Implementa interfaces, experiência de uso no cliente e integração com serviços backend. Garante acessibilidade, desempenho percebido e consistência visual quando aplicável. Trabalha em par com backend e design para entregas de ponta a ponta.' WHERE id = 4;
UPDATE roles SET description = 'Define e faz evoluir a estrutura do sistema: componentes, integrações, padrões e decisões que reduzem risco técnico. Equilibra necessidades atuais com capacidade de mudar o sistema ao longo do tempo e com custo de manutenção. Documenta decisões relevantes para alinhamento da equipe.' WHERE id = 5;
UPDATE roles SET description = 'Levanta, analisa e especifica requisitos funcionais e não funcionais com rastreabilidade. Valida entendimento com partes interessadas e reduz ambiguidade antes da construção. Foco em especificação clara e verificável, não apenas em atas de reunião.' WHERE id = 6;
UPDATE roles SET description = 'Planeja e executa estratégias de teste (manuais e automatizadas) para revelar defeitos antes da produção. Define critérios de aceitação testáveis e apoia os critérios de pronto acordados pela equipe (Definition of Done). Atua como guardião da qualidade do produto, sem bloquear entregas de forma burocrática.' WHERE id = 7;
UPDATE roles SET description = 'Automatiza compilação, teste, implantação e observabilidade para entregas repetíveis e seguras. Configura pipelines de integração e entrega contínuas e infraestrutura como código quando cabível. Reduz atrito entre desenvolvimento e operação.' WHERE id = 8;
UPDATE roles SET description = 'Pesquisa necessidades de uso, propõe fluxos e protótipos que reduzem risco de usabilidade. Traduz objetivos de negócio em soluções compreensíveis para quem usa o produto. Entrega artefatos de design que orientam implementação, não apenas aparência visual.' WHERE id = 9;
UPDATE roles SET description = 'Coordena decisões técnicas do time de desenvolvimento no dia a dia da entrega. Facilita alinhamento entre membros, desbloqueia dúvidas de implementação e revisa código crítico. Atua no escopo da equipe, em contraste com governança técnica mais ampla.' WHERE id = 10;
UPDATE roles SET description = 'Papel orientado ao Kanban: cuida do desenho e saúde do fluxo de valor (políticas, limites de trabalho em progresso, cadências de reunião). Facilita melhoria contínua do sistema de trabalho com base em métricas e retorno da equipe. Não substitui gestão de produto, mas otimiza como o trabalho flui.' WHERE id = 11;
UPDATE roles SET description = 'Prioriza demandas entrantes conforme classes de serviço, capacidade e risco do fluxo Kanban. Equilibra urgências com trabalho padrão sem estourar limites de trabalho em progresso. Conecta expectativas de clientes internos ou externos à taxa real de entrega.' WHERE id = 12;
UPDATE roles SET description = 'Orienta a equipe na adoção disciplinada das práticas de Extreme Programming (XP). Ajuda a manter rituais como jogo de planejamento, testes guiados pelo teste e integração contínua na rotina. Atua como mentor de processo e engenharia, não como gerente de tarefas.' WHERE id = 13;
UPDATE roles SET description = 'Representante das partes interessadas disponível para esclarecer requisitos e validar entregas com frequência. No XP, a proximidade reduz mal-entendidos e acelera retorno sobre valor entregue. Participa de decisões de escopo e aceitação, não apenas aprova documentos finais.' WHERE id = 14;
UPDATE roles SET description = 'Coordena escopo, cronograma, recursos e riscos quando o contexto exige gestão formal (ex.: RUP ou projetos regulados). Comunica status e dependências organizacionais. Complementa papéis ágeis sem substituir a responsabilidade formal sobre produto ou equipe.' WHERE id = 15;
UPDATE roles SET description = 'Atua em camadas de interface e servidor para entregar funcionalidades completas. Útil em times enxutos ou em histórias que exigem percurso vertical rápido. Mantém mesmos padrões de qualidade e revisão que especialistas de cada camada.' WHERE id = 16;
UPDATE roles SET description = 'Detém conhecimento profundo do negócio ou regulatório que o software suporta. Esclarece regras, exceções e linguagem comum entre negócio e técnica. Reduz retrabalho por interpretações incorretas do domínio.' WHERE id = 17;
UPDATE roles SET description = 'Conduz reuniões e dinâmicas (planejamento, retrospectiva, oficinas) com neutralidade e foco em resultado. Não assume necessariamente a responsabilidade formal de Scrum Master ou Flow Manager. Útil quando a equipe precisa de condução sem alterar papéis do processo.' WHERE id = 18;
UPDATE roles SET description = 'Traduz objetivos estratégicos e processos de negócio em necessidades priorizáveis para produto ou projeto. Ponte entre áreas não técnicas e equipe de entrega. Diferencia-se do analista de requisitos por foco em valor e processo, antes do detalhamento formal.' WHERE id = 19;
UPDATE roles SET description = 'Governa padrões de engenharia, qualidade e coerência técnica além de uma única equipe. Define diretrizes compartilhadas, apoia decisões difíceis e eleva maturidade de práticas (testes, segurança, revisão). Contrasta com o Tech Lead, mais voltado à coordenação do time no sprint ou iteração.' WHERE id = 20;
UPDATE artifacts SET description = 'Síntese do problema, oportunidade, partes interessadas e direção desejada do produto ou projeto. Ancora decisões de escopo e comunica o porquê antes do como. Comum na iniciação (RUP, Scrum ou XP) para alinhar expectativas.' WHERE id = 1;
UPDATE artifacts SET description = 'Lista emergente e ordenada de itens que ainda podem entregar valor (histórias, épicos, demandas). Reflete prioridade atual, não um plano fixo de longo prazo. Fonte única do que pode ser selecionado para sprints ou iterações.' WHERE id = 2;
UPDATE artifacts SET description = 'Detalhamento estruturado de requisitos funcionais, não funcionais e regras de negócio. Reduz ambiguidade para arquitetura, testes e implementação. Deve ser rastreável a casos de uso, histórias ou objetivos de negócio.' WHERE id = 3;
UPDATE artifacts SET description = 'Representação visual de componentes, integrações e fluxos principais do sistema. Apoia discussão técnica e integração de novos membros. Artefato opcional quando a equipe já compartilha o mesmo entendimento por outro meio.' WHERE id = 4;
UPDATE artifacts SET description = 'Esboços de tela, wireframes ou protótipo interativo que antecipam a experiência de uso antes da implementação. Reduz retrabalho em telas e fluxos críticos. Opcional quando o risco de usabilidade ou alinhamento visual justificar.' WHERE id = 5;
UPDATE artifacts SET description = 'Estratégia e casos que cobrem funcionalidade, regressão e critérios de aceitação. Define o que será verificado e como saber que a entrega está correta. Evolui junto com o produto, não é documento único congelado.' WHERE id = 6;
UPDATE artifacts SET description = 'Implementação versionada do software, normalmente em repositório Git com histórico e revisões. É o artefato central de construção incremental. Deve refletir os critérios de pronto acordados pela equipe.' WHERE id = 7;
UPDATE artifacts SET description = 'Métricas de cobertura de testes automatizados (linhas, ramos ou requisitos cobertos). Apoia decisões sobre risco residual de qualidade. Opcional quando a equipe já monitora cobertura na integração contínua.' WHERE id = 8;
UPDATE artifacts SET description = 'Registro das mudanças entregues: funcionalidades, correções, mudanças incompatíveis e orientações de uso. Comunica consumidores internos ou externos sobre o que mudou na versão. Complementa o incremento técnico com narrativa de produto.' WHERE id = 9;
UPDATE artifacts SET description = 'Instruções para compilação, configuração, publicação e reversão em ambientes alvo. Torna a implantação repetível e auditável. Opcional em times maduros com pipeline totalmente automatizado e documentado.' WHERE id = 10;
UPDATE artifacts SET description = 'Visualização do fluxo de trabalho em colunas (e eventualmente raias), refletindo estados reais do serviço. Torna limites de trabalho em progresso e gargalos visíveis para todo o time. Base operacional do método Kanban no catálogo.' WHERE id = 11;
UPDATE artifacts SET description = 'Regras escritas de quando um item entra, avança ou sai de cada etapa do fluxo. Complementam limites de trabalho em progresso com critérios de qualidade e compromisso. Reduzem interpretações divergentes do mesmo quadro.' WHERE id = 12;
UPDATE artifacts SET description = 'Indicadores de tempo desde a entrada até a conclusão e tempo em execução ativa. Fundamentam melhoria baseada em dados no Kanban. Opcional como artefato formal quando métricas já vivem na ferramenta.' WHERE id = 13;
UPDATE artifacts SET description = 'Descrição concisa de valor para um usuário ou persona, em geral com critérios de aceitação. Unidade comum de trabalho em Scrum e XP. Deve ser pequena o suficiente para completar dentro de um ciclo curto.' WHERE id = 14;
UPDATE artifacts SET description = 'Versão do produto que atende aos critérios de pronto e agrega valor utilizável ao anterior. No Scrum, é resultado de uma sprint, em outros fluxos, entrega concluída conforme critérios de saída.' WHERE id = 15;
UPDATE artifacts SET description = 'Arquitetura de referência estável o suficiente para guiar construção iterativa (conceito RUP). Não impede evolução, mas fixa decisões estruturais já validadas. Reduz risco de implementar em larga escala sobre base instável.' WHERE id = 16;
UPDATE artifacts SET description = 'Modelagem de atores e casos de uso que capturam comportamento essencial do sistema. Apoia escopo e testes de aceitação em abordagens orientadas a casos de uso. Foca no essencial antes de detalhar casos raros.' WHERE id = 17;
UPDATE artifacts SET description = 'Pacote de software integrado e identificado (versão) pronto para testes ou demonstração. Resultado típico de uma iteração de construção. Deve ser reproduzível a partir do controle de versão e pipeline acordados.' WHERE id = 18;
UPDATE artifacts SET description = 'Prova de conceito focada em incerteza técnica (desempenho, integração, tecnologia nova). Mitiga risco antes de comprometer a arquitetura ou o cronograma. Opcional quando há risco arquitetural explícito a validar.' WHERE id = 19;
UPDATE artifacts SET description = 'Conjunto de itens selecionados e plano de entrega para o ciclo corrente (sprint no Scrum ou iteração no XP). Deriva do backlog do produto e reflete compromisso da equipe para aquela janela de tempo. Evolui durante o ciclo conforme aprendizado, dentro das regras do processo.' WHERE id = 20;
UPDATE tools SET description = 'Plataforma de gestão ágil para backlog, sprints, quadros e rastreamento de demandas. Centraliza priorização, fluxo de trabalho e histórico de entregas. Muito usada em Scrum e combinações com Kanban.' WHERE id = 1;
UPDATE tools SET description = 'Hospedagem de repositórios Git com solicitações de merge, revisão de código e automações. Suporta integração contínua e colaboração assíncrona. Base comum para versionamento e governança de mudanças.' WHERE id = 2;
UPDATE tools SET description = 'Ferramenta colaborativa de design de interfaces e protótipos interativos. Permite alinhar experiência de uso antes ou durante a implementação. Útil quando o risco de usabilidade ou a passagem design-desenvolvimento é alto.' WHERE id = 3;
UPDATE tools SET description = 'Análise estática de código para detectar defeitos, vulnerabilidades e dívidas técnicas. Integra-se a pipelines para retorno contínuo sobre qualidade. Complementa testes automatizados, não os substitui.' WHERE id = 4;
UPDATE tools SET description = 'Containerização para empacotar aplicações e dependências de forma reproduzível. Facilita ambientes de desenvolvimento, teste e produção consistentes. Reduz diferenças entre máquina local e servidor.' WHERE id = 5;
UPDATE tools SET description = 'Cliente para construir, testar e documentar APIs REST. Apoia validação de contratos antes e depois da implementação. Útil em times com integrações entre serviços.' WHERE id = 6;
UPDATE tools SET description = 'Repositório de documentação colaborativa: visão, requisitos, registros de decisão e atas. Mantém conhecimento acessível além do código. Complementa ferramentas ágeis quando documentação formal é necessária.' WHERE id = 7;
UPDATE tools SET description = 'Servidor de automação para pipelines de compilação, teste e implantação. Orquestra jobs em ambientes internos ou híbridos. Alternativa ou complemento a GitHub Actions conforme infraestrutura.' WHERE id = 8;
UPDATE tools SET description = 'Editor de diagramas (arquitetura, fluxos, modelo C4) integrável a wikis e documentos. Apoia comunicação visual de decisões técnicas. Leve para linhas de base e mapas de fluxo Kanban.' WHERE id = 9;
UPDATE tools SET description = 'Comunicação síncrona e assíncrona da equipe com canais e integrações. Facilita dailies remotas, alertas de integração contínua e coordenação rápida. Não substitui registro formal em backlog ou documentação quando exigido.' WHERE id = 10;
UPDATE tools SET description = 'Quadros visuais simples para fluxo Kanban ou listas de trabalho. Adequado a times pequenos ou fluxos leves. Limites de trabalho em progresso podem ser representados com regras de coluna e etiquetas.' WHERE id = 11;
UPDATE tools SET description = 'Quadro digital para oficinas, mapas de fluxo de valor e dinâmicas de retrospectiva. Apoia facilitação remota e co-criação. Comum na descoberta Kanban e sessões de alinhamento entre áreas.' WHERE id = 12;
UPDATE guidelines SET description = 'Critérios mínimos para um item entrar em sprint ou iteração (valor claro, critérios de aceitação, dependências conhecidas). Evita comprometer trabalho ainda nebuloso. Quando ignorada, aumenta bloqueios e replanejamento no meio do ciclo.' WHERE id = 1;
UPDATE guidelines SET description = 'Critérios mínimos para considerar uma entrega concluída (testes, revisão, documentação acordada). Garante incremento utilizável e sustentável. Violações criam dívida oculta e falsa sensação de progresso.' WHERE id = 2;
UPDATE guidelines SET description = 'Toda mudança relevante passa por solicitação de merge revisada por pelo menos um par qualificado. Captura defeitos e dissemina conhecimento antes da integração. Sem revisão, a qualidade depende só do autor original.' WHERE id = 3;
UPDATE guidelines SET description = 'Novas funcionalidades mantêm cobertura automatizada acima do limiar acordado (ex.: 80%). Sinaliza risco de regressão em áreas tocadas. Exceções devem ser conscientes e temporárias.' WHERE id = 4;
UPDATE guidelines SET description = 'Mensagens de commit seguem padrão convencional (tipo, escopo, descrição) para histórico legível e registro automático de versões. Facilita rastreio de mudanças. Commits ambíguos dificultam auditoria e reversão.' WHERE id = 5;
UPDATE guidelines SET description = 'Atividades críticas ou de alto aprendizado são desenvolvidas em par (piloto e copiloto). Prática central do XP para qualidade e transferência de conhecimento. Aplica-se onde o processo vincula a prática, não em todo momento.' WHERE id = 6;
UPDATE guidelines SET description = 'Integrações frequentes na branch principal compartilhada, com branches de vida curta. Reduz conflitos grandes de merge e mantém o software integrado. Conflita com branches longas isoladas por semanas.' WHERE id = 7;
UPDATE guidelines SET description = 'Decisões arquiteturais relevantes registradas formalmente (registro de decisão de arquitetura): contexto, alternativas e consequências. Preserva memória quando pessoas saem do time. Decisões só na cabeça se perdem com rotatividade.' WHERE id = 8;
UPDATE guidelines SET description = 'Novas APIs e fluxos sensíveis validam autenticação, autorização e tratamento de dados conforme política da organização. Incorpora segurança no desenho, não só em teste de invasão no fim. Omissões geram vulnerabilidades caras de corrigir tarde.' WHERE id = 9;
UPDATE guidelines SET description = 'Lições aprendidas registradas ao final de cada ciclo (sprint, iteração ou cadência Kanban). Transforma inspeção em ações de melhoria concretas. Sem registro, a equipe repete os mesmos problemas.' WHERE id = 10;
UPDATE guidelines SET description = 'Respeitar limites de trabalho em progresso por coluna ou etapa do fluxo Kanban. Protege a taxa de entrega e torna gargalos visíveis. Ultrapassar o limite simula produtividade enquanto aumenta o tempo de ciclo.' WHERE id = 11;
UPDATE guidelines SET description = 'Escrever ou esqueletar testes antes ou junto ao código (desenvolvimento guiado por testes). Guia desenho testável e documenta comportamento esperado. Prática forte no XP: abandoná-la aumenta regressões e medo de refatorar.' WHERE id = 12;
UPDATE templates SET description = 'Modelo para registrar histórias no backlog. Campos recomendados: título resumido, persona ou tipo de usuário, narrativa (Como [persona] quero [ação] para [benefício]), contexto ou regra de negócio (opcional), critérios de aceitação em lista numerada e testável, dependências ou premissas (opcional), estimativa de esforço (opcional). Garante valor explícito antes da implementação e base para refinamento e testes de aceitação.' WHERE id = 1;
UPDATE templates SET description = 'Modelo com identificador e nome do caso, objetivo ou requisito rastreado, pré-condições, passos numerados (ação e dados de entrada), resultado esperado, pós-condições, prioridade quando couber e status de execução. Padroniza testes manuais ou automatizados e liga requisito, teste e defeito.' WHERE id = 2;
UPDATE templates SET description = 'Modelo de registro de decisão arquitetural: número e título, data e status (proposto, aceito, substituído), contexto e problema, decisão, alternativas com prós e contras, consequências e referências. Um registro por decisão relevante, em linguagem clara para quem entrar no time depois.' WHERE id = 3;
UPDATE templates SET description = 'Ata com data e participantes, meta da sprint, itens selecionados do backlog, capacidade e compromisso da equipe, plano inicial de entrega, riscos ou impedimentos e confirmação de prontidão dos itens. Apoia o tempo fixo da sprint e o alinhamento até a daily e a review.' WHERE id = 4;
UPDATE templates SET description = 'Registro com data e formato (ex.: manter, parar, começar), pontos positivos, dificuldades, ideias de melhoria, ações com responsável e prazo e acompanhamento da retro anterior. Converte conversa em melhorias concretas para o próximo ciclo.' WHERE id = 5;
UPDATE templates SET description = 'Descrição da mudança, tipo (correção, funcionalidade, refatoração), vínculo com issue ou história, verificação (testes, documentação, impacto em API), mudanças incompatíveis se houver, evidências úteis e revisores sugeridos. Alinha autor e revisor sobre entrega pronta no código.' WHERE id = 6;
UPDATE templates SET description = 'Esqueleto OpenAPI: informações gerais, servidores, endpoints (método, caminho, resumo), parâmetros e corpo, respostas com códigos e exemplos, autenticação e erros padronizados. Contrato entre backend, frontend e integradores.' WHERE id = 7;
UPDATE templates SET description = 'Título, severidade, ambiente e versão, passos para reproduzir, comportamento esperado e observado, frequência, evidências (captura, log) e triagem. Relatórios completos encurtam o ciclo entre QA e desenvolvimento.' WHERE id = 8;
UPDATE templates SET description = 'Versão e data, resumo, novidades, correções, mudanças incompatíveis e migração, instruções de atualização, problemas conhecidos. Comunica a versão para usuários, suporte e operação.' WHERE id = 9;
UPDATE templates SET description = 'Níveis contexto (sistema e externos), contêineres (aplicações e dados), componentes internos e código (opcional), cada um com nome, responsabilidade e relações. Ajusta o detalhe à audiência (negócio ou implementação).' WHERE id = 10;
UPDATE templates SET description = 'Nome, atores, resumo, pré-condições, fluxo principal numerado, alternativos e exceções, pós-condições e requisitos especiais. Apoia RUP e especificação orientada a comportamento.' WHERE id = 11;
UPDATE templates SET description = 'Por coluna Kanban: nome, critérios de entrada e saída, limite de trabalho em progresso, classe de serviço e quem puxa ou move itens. Deixa regras do fluxo explícitas para toda a equipe.' WHERE id = 12;

            DELETE FROM rel_activity__sub_activities WHERE activity_id = 1001 AND sub_activities_id = 1002;
            INSERT INTO rel_activity__sub_activities (activity_id, sub_activities_id)
SELECT 1001, 1013 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rel_activity__sub_activities WHERE activity_id = 1001 AND sub_activities_id = 1013);
            INSERT INTO rel_activity__sub_activities (activity_id, sub_activities_id)
SELECT 1013, 1002 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rel_activity__sub_activities WHERE activity_id = 1013 AND sub_activities_id = 1002);
